package org.xingmu.tv;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
public final class CatalogRepository {
 private static final java.util.concurrent.atomic.AtomicBoolean warming=new java.util.concurrent.atomic.AtomicBoolean();public static void prewarm(Context c){Context app=c.getApplicationContext();if(!warming.compareAndSet(false,true))return;new Thread(()->{try{new CatalogRepository(app).load();}catch(IOException ignored){}finally{warming.set(false);}},"catalog-prewarm").start();}
 private static List<CatalogItem> cached;private static String cacheKey;public static synchronized void invalidate(){cached=null;cacheKey=null;}
 private final Context context;public CatalogRepository(Context c){context=c.getApplicationContext();}
 public static String read(InputStream input)throws IOException{if(input==null)throw new IOException("无法打开目录");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>1_000_000)throw new IOException("目录超过 1 MB");out.write(buf,0,n);}return out.toString("UTF-8");}}
 public List<CatalogItem> load()throws IOException{synchronized(CatalogRepository.class){File subscriptionFile=new File(context.getFilesDir(),"myiptv-catalog.json"),customFile=new File(context.getFilesDir(),"authorized-catalog.json"),zbdsFile=new File(context.getFilesDir(),"zbds-catalog.json");String key=subscriptionFile.lastModified()+":"+subscriptionFile.length()+":"+customFile.lastModified()+":"+customFile.length()+":"+zbdsFile.lastModified()+":"+zbdsFile.length();if(cached!=null&&key.equals(cacheKey))return new ArrayList<>(cached);Map<String,CatalogItem> all=new LinkedHashMap<>();for(CatalogItem i:CatalogParser.parse(read(context.getAssets().open("catalog.json"))))all.put(i.id,i);File subscription=new File(context.getFilesDir(),"myiptv-catalog.json");try{String json=subscription.exists()?read(new FileInputStream(subscription)):read(context.getAssets().open("myiptv-catalog.json"));for(CatalogItem i:CatalogParser.parse(json))all.put(i.id,i);}catch(IOException ignored){}if(zbdsFile.exists())try{for(CatalogItem i:CatalogParser.parse(read(new FileInputStream(zbdsFile))))all.put(i.id,i);}catch(IOException ignored){}File user=new File(context.getFilesDir(),"authorized-catalog.json");if(user.exists())for(CatalogItem i:CatalogParser.parse(read(new FileInputStream(user))))all.put(i.id,i);cached=new ArrayList<>(all.values());cacheKey=key;return new ArrayList<>(cached);}}
 public int save(String json)throws IOException{List<CatalogItem> items=CatalogParser.parse(json);File file=new File(context.getFilesDir(),"authorized-catalog.json"),temp=new File(context.getFilesDir(),"authorized-catalog.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));out.getFD().sync();}if(!temp.renameTo(file))throw new IOException("目录保存失败");invalidate();return items.size();}
 public synchronized int merge(String content,String section,String country)throws IOException{if(TvBoxConfig.recognises(content))return new SourceRepository(context).save(content,null);String json=PlaylistImporter.convert(content,section,country);List<CatalogItem> parsed=CatalogParser.parse(json);try{LinkedHashMap<String,JSONObject> combined=new LinkedHashMap<>();File existing=new File(context.getFilesDir(),"authorized-catalog.json");if(existing.exists()){JSONArray old=new JSONObject(read(new FileInputStream(existing))).getJSONArray("items");for(int n=0;n<old.length();n++){JSONObject item=old.getJSONObject(n);combined.put(item.getString("id"),item);}}JSONArray incoming=new JSONObject(json).getJSONArray("items");for(int n=0;n<incoming.length();n++){JSONObject item=incoming.getJSONObject(n);combined.put(item.getString("id"),item);}JSONArray result=new JSONArray();for(JSONObject item:combined.values())result.put(item);save(new JSONObject().put("authorized",true).put("items",result).toString());return parsed.size();}catch(JSONException e){throw new IOException("目录合并失败",e);}}
 public int fetch(String url,String section,String country)throws IOException{if(!CatalogParser.safeUrl(url))throw new IOException("请输入公开 HTTPS 授权目录地址");HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setConnectTimeout(6000);connection.setReadTimeout(6000);connection.setInstanceFollowRedirects(false);try{if(connection.getResponseCode()!=200)throw new IOException("目录请求失败，请检查地址与网络");String text=read(connection.getInputStream());return TvBoxConfig.recognises(text)?new SourceRepository(context).save(text,url):merge(text,section,country);}finally{connection.disconnect();}}
 public void clear(){new File(context.getFilesDir(),"authorized-catalog.json").delete();invalidate();}
}
